import React from 'react';
import { motion } from 'framer-motion';
import { useAuth } from '../../context/AuthContext';
import { useTheme } from '../../context/ThemeContext';
import { useLanguageContext } from '../../context/LanguageContext';
import BackgroundAnimation from '../../components/BackgroundAnimation';
import RootPanel from './RootPanel';

const Dashboard = () => {
  const { currentUser, logout } = useAuth();
  const { isDarkMode, colors } = useTheme();
  const { t, language } = useLanguageContext();

  return (
    <div style={{ position: 'relative', minHeight: '100vh' }}>
      {/* بک‌گراند مثل سایت اصلی */}
      <BackgroundAnimation />

      <div style={{
        position: 'relative',
        zIndex: 1,
        minHeight: '100vh',
        padding: '100px 20px 40px',
        direction: 'rtl',
      }}>
        <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
          {/* Header */}
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            style={{
              background: `${colors.card}ee`,
              backdropFilter: 'blur(20px)',
              border: `1px solid ${colors.border}`,
              borderRadius: '20px',
              padding: '25px 30px',
              marginBottom: '25px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              flexWrap: 'wrap',
              gap: '15px',
            }}
          >
            <div>
              <h2 style={{ color: colors.text, margin: 0, fontSize: '1.3rem' }}>
                👋 {language === 'fa' ? 'خوش آمدید' : 'Welcome'}, {currentUser?.name}
              </h2>
              <p style={{ color: colors.textSecondary, margin: '5px 0 0', fontSize: '0.9rem' }}>
                {currentUser?.role === 'root' ? '🔑 Super Admin' : '🛡️ Admin'}
              </p>
            </div>
            <motion.button
              whileHover={{ scale: 1.03 }}
              whileTap={{ scale: 0.97 }}
              onClick={logout}
              style={{
                padding: '12px 25px',
                background: 'rgba(255,68,68,0.15)',
                border: '1px solid rgba(255,68,68,0.3)',
                borderRadius: '12px',
                color: '#ff4444',
                cursor: 'pointer',
                fontWeight: 600,
                fontSize: '0.9rem',
                fontFamily: 'inherit',
              }}
            >
              🚪 {language === 'fa' ? 'خروج' : 'Logout'}
            </motion.button>
          </motion.div>

          {/* Stats */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            style={{
              background: `${colors.card}ee`,
              backdropFilter: 'blur(20px)',
              border: `1px solid ${colors.border}`,
              borderRadius: '20px',
              padding: '30px',
              marginBottom: '25px',
            }}
          >
            <h3 style={{ color: colors.text, marginBottom: '15px' }}>
              📊 {language === 'fa' ? 'آمار سرور' : 'Server Stats'}
            </h3>
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
              gap: '15px',
            }}>
              {[
                { label: language === 'fa' ? 'کاربران آنلاین' : 'Online Users', value: '۱۲۴', icon: '🟢', color: '#4CAF50' },
                { label: language === 'fa' ? 'کانال‌ها' : 'Channels', value: '۴۲', icon: '📺', color: '#2196F3' },
                { label: language === 'fa' ? 'پینگ' : 'Ping', value: '۲۳ms', icon: '📡', color: '#FF9800' },
              ].map((stat, i) => (
                <div key={i} style={{
                  background: colors.primary,
                  borderRadius: '14px',
                  padding: '20px',
                  border: `1px solid ${colors.border}`,
                }}>
                  <div style={{ fontSize: '1.5rem', marginBottom: '8px' }}>{stat.icon}</div>
                  <p style={{ color: colors.textSecondary, fontSize: '0.85rem', marginBottom: '5px' }}>{stat.label}</p>
                  <p style={{ color: stat.color, fontSize: '1.8rem', fontWeight: 700, margin: 0 }}>{stat.value}</p>
                </div>
              ))}
            </div>
          </motion.div>

          {/* Root Panel */}
          {currentUser?.role === 'root' && <RootPanel />}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
